WHO = {'column': [('muefleyeben', 97005), ('einsof', 0), ('maefhlsof', 97197), ('bridum', 97261), ('zeecelldmicr', 97261), ('visha', 97261), ('bridldmicro', 0), ('einsof', 0)], 'temple': [('einlhlysen', 97197), ('zecyfsen', 100142), ('weiweeyeben', 100718), ('muefldum', 0), ('zecyfgepy', 0), ('unel', 104174), ('einlhlysen', 0), ('weiweeyeben', 0)], 'tree': [('unel', 97261), ('mueflflhisha', 97261), ('aprilfools', 0), ('psiloeyeben', 0), ('aprillfhlsof', 98477), ('visha', 0), ('aprilepy', 0), ('aprilepy', 98925)], 'bridge': [('psiloldmicr', 0), ('alphafoldmicro', 98669), ('mueflldmicr', 0), ('alphafoldmicro', 107054), ('alphafoldmicro', 0), ('psiloldmicr', 109742)], 'manor': [('aprilepy', 0), ('mueflechisha', 101998), ('zecyhepy', 102318), ('bridum', 0), ('aprilfools', 0), ('brifocren', 106862), ('zeecelhisha', 107758)], 'tower': [('mueflhepy', 0), ('aprilcuya', 99885), ('psiloceyeben', 100398), ('quhlsof', 101806), ('muefleyeben', 103662), ('bridelecut', 0), ('aprilcuya', 111404), ('psiloceyeben', 111788)], 'castle': [('aprilleyeben', 101998)]}

EPI_RX = re.compile(
    r"^(?:what (?:has|have) (?P<a>[\w'\- ]{2,24}?) (?:done|been doing)"
    r"|what happened (?:with|to) (?P<b>[\w'\- ]{2,24}?))[?.! ]*$", re.I)
WHO_RX = re.compile(
    r"^who (?:built|made|raised) (?:a |an |the )?(?P<k>[\w \-]{2,24}?)[?.! ]*$", re.I)


class OracleReleaseRuntimeW319(OracleReleaseRuntimeW318):
    """Base + episodic recall. Fires only on bound episodes; else the chain answers."""

    def chat(self, text: str, session_id: str = "default") -> dict:
        s = " ".join(str(text).strip().split())
        m = EPI_RX.match(s)
        if m:
            actor = (m.group("a") or m.group("b") or "").strip().lower()
            eps = EPI.get(actor)
            if eps:
                bits = "; ".join(f"at tick {t} {v} {o}" for t, v, o in eps[-5:])
                pending = getattr(self, "_pending_conversion", None)
                if pending is None:
                    pending = self._pending_conversion = {}
                pending[session_id] = {"construction": "EPISODIC_RECALL",
                                        "from": s[:80], "to": f"episodes({actor})",
                                        "produced_by": "oracle_fold_worker_v4"}
                return {"status": "answered", "path": "worker:episodic",
                         "response": f"The record holds for {actor}: {bits}. "
                                     f"[world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "actor": actor,
                                         "episodes": len(eps)},
                         "latency_ms": 1}
        w = WHO_RX.match(s)
        if w:
            kind = w.group("k").strip().lower()
            hits = WHO.get(kind) or WHO.get(kind.rstrip("s"))
            if hits:
                bits = ", ".join(f"{a} (tick {t})" for a, t in hits[-4:])
                return {"status": "answered", "path": "worker:episodic_who",
                         "response": f"By the world record, {kind}s were raised by "
                                     f"{bits}. [world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "object": kind},
                         "latency_ms": 1}
        return super().chat(s, session_id)
